package com.zenpanel.app

import android.content.Context
import android.content.SharedPreferences

/**
 * Lightweight persistent store for panel state (Browsec toggle + traffic log),
 * the native equivalent of the PWA LocalStorage cache.
 */
class PanelStore(context: Context) {

    private val prefs: SharedPreferences =
        context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    var browsecEnabled: Boolean
        get() = prefs.getBoolean(KEY_BROWSEC, false)
        set(value) = prefs.edit().putBoolean(KEY_BROWSEC, value).apply()

    val trafficLog: List<String>
        get() = prefs.getString(KEY_LOG, "")
            ?.split('\n')
            ?.filter { it.isNotBlank() }
            ?: emptyList()

    fun logTraffic(entry: String) {
        val updated = (trafficLog + entry).takeLast(MAX_LOG)
        prefs.edit().putString(KEY_LOG, updated.joinToString("\n")).apply()
    }

    fun clearTraffic() {
        prefs.edit().remove(KEY_LOG).apply()
    }

    companion object {
        private const val PREFS = "zen_panel_store"
        private const val KEY_BROWSEC = "browsec_enabled"
        private const val KEY_LOG = "traffic_log"
        private const val MAX_LOG = 50
    }
}

package com.zenpanel.app

import android.app.NotificationChannel
import android.app.NotificationManager
import android.content.Context
import android.os.Build
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat

/**
 * Native replacement for the PWA Notification API.
 */
object Notifications {

    const val CHANNEL_ID = "zen_panel_default"
    private const val NOTIFICATION_ID = 1001

    fun ensureChannel(context: Context) {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = context.getSystemService(NotificationManager::class.java) ?: return
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            context.getString(R.string.channel_name),
            NotificationManager.IMPORTANCE_DEFAULT
        ).apply {
            description = context.getString(R.string.channel_description)
        }
        manager.createNotificationChannel(channel)
    }

    fun show(context: Context, title: String, body: String) {
        ensureChannel(context)
        val notification = NotificationCompat.Builder(context, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(title)
            .setContentText(body)
            .setPriority(NotificationCompat.PRIORITY_DEFAULT)
            .setAutoCancel(true)
            .build()
        try {
            NotificationManagerCompat.from(context).notify(NOTIFICATION_ID, notification)
        } catch (_: SecurityException) {
            // POST_NOTIFICATIONS permission missing on API 33+.
        }
    }
}

package com.zenpanel.app

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.Uri
import android.os.Build
import android.os.Bundle
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import com.zenpanel.app.databinding.ActivityMainBinding
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
    private lateinit var store: PanelStore

    private val timeFormat = SimpleDateFormat("HH:mm:ss", Locale.US)

    private val notificationPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.RequestPermission()) { granted ->
            if (granted) {
                postNotification(getString(R.string.notify_enabled_body))
            } else {
                toast(getString(R.string.notify_permission_denied))
            }
        }

    private val connectivityManager by lazy {
        getSystemService(ConnectivityManager::class.java)
    }

    private val networkCallback = object : ConnectivityManager.NetworkCallback() {
        override fun onAvailable(network: Network) = runOnUiThread { updateStatus(true) }
        override fun onLost(network: Network) = runOnUiThread { updateStatus(isOnline()) }
        override fun onCapabilitiesChanged(network: Network, caps: NetworkCapabilities) =
            runOnUiThread { updateStatus(caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)) }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        store = PanelStore(this)
        Notifications.ensureChannel(this)

        binding.buttonSearch.setOnClickListener { runSearch() }
        binding.buttonTestNotification.setOnClickListener { requestNotification() }
        binding.buttonLaunchExtension.setOnClickListener { launchExtension() }
        binding.buttonBrowsec.setOnClickListener { toggleBrowsec() }
        binding.buttonClearLog.setOnClickListener {
            store.clearTraffic()
            renderTraffic()
        }

        updateStatus(isOnline())
        renderBrowsec()
        renderTraffic()
    }

    override fun onStart() {
        super.onStart()
        connectivityManager?.registerDefaultNetworkCallback(networkCallback)
    }

    override fun onStop() {
        super.onStop()
        try {
            connectivityManager?.unregisterNetworkCallback(networkCallback)
        } catch (_: IllegalArgumentException) {
            // Callback was not registered.
        }
    }

    private fun isOnline(): Boolean {
        val cm = connectivityManager ?: return false
        val network = cm.activeNetwork ?: return false
        val caps = cm.getNetworkCapabilities(network) ?: return false
        return caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
    }

    private fun updateStatus(online: Boolean) {
        binding.textStatus.text =
            getString(if (online) R.string.status_online else R.string.status_offline)
        binding.textStatus.setTextColor(
            ContextCompat.getColor(this, if (online) R.color.status_online else R.color.status_offline)
        )
    }

    private fun runSearch() {
        val query = binding.inputSearch.text?.toString()?.trim().orEmpty()
        if (query.isEmpty()) return
        val url = "https://www.google.com/search?q=" + Uri.encode(query)
        store.logTraffic("${timeFormat.format(Date())}  ←  $query")
        renderTraffic()
        startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)))
        binding.inputSearch.setText("")
    }

    private fun requestNotification() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        } else {
            postNotification(getString(R.string.notify_enabled_body))
        }
    }

    private fun postNotification(body: String) {
        Notifications.show(this, getString(R.string.app_name), body)
    }

    private fun launchExtension() {
        startActivity(Intent(this, ExtensionActivity::class.java))
    }

    private fun toggleBrowsec() {
        store.browsecEnabled = !store.browsecEnabled
        renderBrowsec()
        val state = if (store.browsecEnabled) R.string.browsec_on else R.string.browsec_off
        toast(getString(state))
    }

    private fun renderBrowsec() {
        val enabled = store.browsecEnabled
        binding.textBrowsecStatus.text =
            getString(if (enabled) R.string.browsec_on else R.string.browsec_off)
        binding.textBrowsecStatus.setTextColor(
            ContextCompat.getColor(this, if (enabled) R.color.status_online else R.color.text_muted)
        )
    }

    private fun renderTraffic() {
        val log = store.trafficLog
        binding.textTraffic.text =
            if (log.isEmpty()) getString(R.string.traffic_empty) else log.joinToString("\n")
    }

    private fun toast(message: String) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
    }
}

package com.zenpanel.app

import android.content.Intent
import android.graphics.Typeface
import android.net.Uri
import android.os.Bundle
import android.view.Gravity
import android.widget.LinearLayout
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import com.zenpanel.app.databinding.ActivityExtensionBinding
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

/**
 * Native port of the PWA extension simulator window.
 */
class ExtensionActivity : AppCompatActivity() {

    private lateinit var binding: ActivityExtensionBinding
    private lateinit var store: PanelStore
    private val timeFormat = SimpleDateFormat("HH:mm:ss", Locale.US)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityExtensionBinding.inflate(layoutInflater)
        setContentView(binding.root)

        store = PanelStore(this)

        binding.buttonExtSearch.setOnClickListener { runSearch() }
        binding.buttonClose.setOnClickListener { finish() }

        showPlaceholder()
    }

    private fun runSearch() {
        val query = binding.inputExtSearch.text?.toString()?.trim().orEmpty()
        if (query.isEmpty()) return

        store.logTraffic("${timeFormat.format(Date())}  ⇄  $query")
        binding.containerResults.removeAllViews()
        for (i in 1..3) {
            addResult("$i. Результат для «$query»")
        }
        binding.inputExtSearch.setText("")
    }

    private fun addResult(text: String) {
        val view = TextView(this).apply {
            this.text = text
            textSize = 15f
            setTextColor(ContextCompat.getColor(this@ExtensionActivity, R.color.text_primary))
            setPadding(24, 28, 24, 28)
            isClickable = true
            setOnClickListener {
                startActivity(
                    Intent(Intent.ACTION_VIEW, Uri.parse("https://www.google.com/search?q=" + Uri.encode(text)))
                )
            }
        }
        binding.containerResults.addView(
            view,
            LinearLayout.LayoutParams(
                LinearLayout.LayoutParams.MATCH_PARENT,
                LinearLayout.LayoutParams.WRAP_CONTENT
            )
        )
    }

    private fun showPlaceholder() {
        val view = TextView(this).apply {
            text = getString(R.string.extension_hint)
            textSize = 14f
            gravity = Gravity.CENTER
            setTextColor(ContextCompat.getColor(this@ExtensionActivity, R.color.text_muted))
            typeface = Typeface.DEFAULT
            setPadding(24, 56, 24, 56)
        }
        binding.containerResults.addView(view)
    }
}

