package com.zenpanel.app

import java.util.UUID

/**
 * A VPN endpoint the user can connect to. The actual encrypted tunnel is provided
 * by a WireGuard configuration that the user supplies (own server or provider).
 */
data class VpnServer(
    val id: String = UUID.randomUUID().toString(),
    val name: String,
    val country: String,
    val countryCode: String,
    val config: String
) {
    fun flag(): String {
        val cc = countryCode.trim().uppercase()
        if (cc.length != 2) return "🌐"
        val base = 0x1F1E6
        val first = base + (cc[0] - 'A')
        val second = base + (cc[1] - 'A')
        return String(Character.toChars(first)) + String(Character.toChars(second))
    }

    fun displayName(): String = flag() + "  " + (if (country.isBlank()) name else country)
}

package com.zenpanel.app

import android.content.Context
import org.json.JSONArray
import org.json.JSONObject

/**
 * Persists the list of VPN servers and which one is selected.
 * Provider agnostic: any WireGuard endpoint can be added.
 */
class ServerRepository(context: Context) {

    private val prefs =
        context.applicationContext.getSharedPreferences(PREFS, Context.MODE_PRIVATE)

    fun all(): List<VpnServer> {
        val raw = prefs.getString(KEY_SERVERS, null) ?: return emptyList()
        return try {
            val array = JSONArray(raw)
            (0 until array.length()).map { i ->
                val o = array.getJSONObject(i)
                VpnServer(
                    id = o.getString("id"),
                    name = o.optString("name"),
                    country = o.optString("country"),
                    countryCode = o.optString("countryCode"),
                    config = o.optString("config")
                )
            }
        } catch (_: Exception) {
            emptyList()
        }
    }

    fun add(server: VpnServer) {
        val list = all() + server
        persist(list)
        if (selectedId == null) selectedId = server.id
    }

    fun remove(id: String) {
        persist(all().filterNot { it.id == id })
        if (selectedId == id) selectedId = all().firstOrNull()?.id
    }

    fun get(id: String?): VpnServer? = all().firstOrNull { it.id == id }

    var selectedId: String?
        get() = prefs.getString(KEY_SELECTED, null)
        set(value) = prefs.edit().putString(KEY_SELECTED, value).apply()

    fun selected(): VpnServer? = get(selectedId)

    private fun persist(list: List<VpnServer>) {
        val array = JSONArray()
        list.forEach { s ->
            array.put(
                JSONObject().apply {
                    put("id", s.id)
                    put("name", s.name)
                    put("country", s.country)
                    put("countryCode", s.countryCode)
                    put("config", s.config)
                }
            )
        }
        prefs.edit().putString(KEY_SERVERS, array.toString()).apply()
    }

    companion object {
        private const val PREFS = "zen_vpn_servers"
        private const val KEY_SERVERS = "servers"
        private const val KEY_SELECTED = "selected"
    }
}

package com.zenpanel.app

import android.content.Context
import com.wireguard.android.backend.Backend
import com.wireguard.android.backend.GoBackend
import com.wireguard.android.backend.Statistics
import com.wireguard.android.backend.Tunnel
import com.wireguard.config.Config
import java.io.StringReader

/**
 * Thin wrapper around the WireGuard userspace backend.
 *
 * This is the real engine: it creates a TUN interface, installs the route table
 * from the supplied config and forwards traffic through the encrypted tunnel.
 * Statistics are read straight from wireguard-go, so speed/counters are real.
 */
class VpnManager(private val context: Context) {

    private val backend: Backend = GoBackend(context)

    private var tunnel: Tunnel? = null

    /** Called whenever the tunnel state changes (UP/DOWN). */
    var onStateChanged: ((Tunnel.State) -> Unit)? = null

    val isUp: Boolean
        get() = state == Tunnel.State.UP

    val state: Tunnel.State
        get() = tunnel?.let {
            try {
                backend.getState(it)
            } catch (_: Exception) {
                Tunnel.State.DOWN
            }
        } ?: Tunnel.State.DOWN

    /**
     * Bring the tunnel up using a wg-quick style configuration text.
     * Throws on invalid config / missing VPN permission.
     */
    @Throws(Exception::class)
    fun up(configText: String): Tunnel.State {
        val parsed: Config = Config.parse(StringReader(configText).buffered())
        val newTunnel = object : Tunnel {
            override fun getName(): String = TUNNEL_NAME

            override fun onStateChange(newState: Tunnel.State) {
                onStateChanged?.invoke(newState)
            }
        }
        tunnel = newTunnel
        return backend.setState(newTunnel, Tunnel.State.UP, parsed)
    }

    fun down(): Tunnel.State {
        val current = tunnel ?: return Tunnel.State.DOWN
        val result = try {
            backend.setState(current, Tunnel.State.DOWN, null)
        } catch (_: Exception) {
            Tunnel.State.DOWN
        }
        tunnel = null
        return result
    }

    fun statistics(): Statistics? {
        val current = tunnel ?: return null
        return try {
            backend.getStatistics(current)
        } catch (_: Exception) {
            null
        }
    }

    companion object {
        private const val TUNNEL_NAME = "zen-panel"
    }
}

