package com.zenpanel.app

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.app.Service
import android.content.Context
import android.content.Intent
import android.content.pm.ServiceInfo
import android.os.Build
import android.os.Handler
import android.os.IBinder
import android.os.Looper
import androidx.core.app.NotificationCompat
import androidx.core.app.NotificationManagerCompat
import androidx.core.app.ServiceCompat
import androidx.core.content.ContextCompat
import com.wireguard.android.backend.Tunnel
import java.util.Locale

/**
 * Foreground service that owns the VPN connection and publishes a live status
 * notification (country + real rx/tx speed, read from the WireGuard backend).
 */
class ZenVpnService : Service() {

    private lateinit var manager: VpnManager
    private val handler = Handler(Looper.getMainLooper())

    private var connected = false
    private var serverLabel = ""
    private var lastRx = 0L
    private var lastTx = 0L
    private var lastTs = 0L
    private var downBps = 0.0
    private var upBps = 0.0

    private val ticker = object : Runnable {
        override fun run() {
            refreshStats()
            handler.postDelayed(this, 1000)
        }
    }

    override fun onBind(intent: Intent?): IBinder? = null

    override fun onCreate() {
        super.onCreate()
        manager = (application as App).vpnManager
        createChannel()
    }

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        when (intent?.action) {
            ACTION_CONNECT -> handleConnect(intent)
            ACTION_DISCONNECT -> handleDisconnect()
        }
        return START_STICKY
    }

    private fun handleConnect(intent: Intent) {
        val config = intent.getStringExtra(EXTRA_CONFIG)
        if (config.isNullOrBlank()) {
            stopSelf()
            return
        }
        serverLabel = intent.getStringExtra(EXTRA_LABEL).orEmpty()

        // Satisfy the foreground-service start deadline before doing slow work.
        startForegroundCompat(buildNotification(getString(R.string.vpn_connecting)))

        try {
            val result = manager.up(config)
            connected = result == Tunnel.State.UP
            lastRx = 0
            lastTx = 0
            lastTs = 0
            refreshStats()
            handler.removeCallbacks(ticker)
            handler.post(ticker)
        } catch (e: Exception) {
            connected = false
            updateNotification(getString(R.string.vpn_error, e.message ?: ""))
            handler.postDelayed({ stopSelf() }, 4000)
        }
    }

    private fun handleDisconnect() {
        manager.down()
        connected = false
        handler.removeCallbacks(ticker)
        ServiceCompat.stopForeground(this, ServiceCompat.STOP_FOREGROUND_REMOVE)
        stopSelf()
    }

    private fun refreshStats() {
        val stats = manager.statistics()
        val rx = stats?.totalRx() ?: 0L
        val tx = stats?.totalTx() ?: 0L
        val now = System.currentTimeMillis()
        if (lastTs != 0L) {
            val dt = (now - lastTs) / 1000.0
            if (dt > 0) {
                downBps = ((rx - lastRx) / dt).coerceAtLeast(0.0)
                upBps = ((tx - lastTx) / dt).coerceAtLeast(0.0)
            }
        }
        lastRx = rx
        lastTx = tx
        lastTs = now
        val line = getString(R.string.vpn_notif_line, formatSpeed(downBps), formatSpeed(upBps))
        updateNotification(line)
    }

    private fun buildNotification(text: String): Notification {
        val open = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        val stop = PendingIntent.getService(
            this,
            1,
            Intent(this, ZenVpnService::class.java).setAction(ACTION_DISCONNECT),
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        val title = if (serverLabel.isBlank()) {
            getString(R.string.app_name)
        } else {
            getString(R.string.vpn_notif_title, serverLabel)
        }
        return NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_notification)
            .setContentTitle(title)
            .setContentText(text)
            .setStyle(NotificationCompat.BigTextStyle().bigText(text))
            .setOngoing(true)
            .setOnlyAlertOnce(true)
            .setContentIntent(open)
            .addAction(0, getString(R.string.disconnect), stop)
            .build()
    }

    private fun updateNotification(text: String) {
        try {
            NotificationManagerCompat.from(this).notify(NOTIFICATION_ID, buildNotification(text))
        } catch (_: SecurityException) {
            // POST_NOTIFICATIONS not granted; the tunnel keeps running regardless.
        }
    }

    private fun startForegroundCompat(notification: Notification) {
        val type = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
            ServiceInfo.FOREGROUND_SERVICE_TYPE_SPECIAL_USE
        } else {
            0
        }
        ServiceCompat.startForeground(this, NOTIFICATION_ID, notification, type)
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(NotificationManager::class.java) ?: return
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        manager.createNotificationChannel(
            NotificationChannel(
                CHANNEL_ID,
                getString(R.string.vpn_channel_name),
                NotificationManager.IMPORTANCE_LOW
            ).apply {
                description = getString(R.string.vpn_channel_description)
                setShowBadge(false)
            }
        )
    }

    private fun formatSpeed(bytesPerSecond: Double): String {
        val units = arrayOf("B/s", "KB/s", "MB/s", "GB/s")
        var value = bytesPerSecond
        var unit = 0
        while (value >= 1024 && unit < units.size - 1) {
            value /= 1024
            unit++
        }
        return String.format(Locale.US, "%.1f %s", value, units[unit])
    }

    companion object {
        const val ACTION_CONNECT = "com.zenpanel.app.action.CONNECT"
        const val ACTION_DISCONNECT = "com.zenpanel.app.action.DISCONNECT"
        private const val EXTRA_CONFIG = "extra_config"
        private const val EXTRA_LABEL = "extra_label"
        private const val CHANNEL_ID = "zen_vpn"
        private const val NOTIFICATION_ID = 4321

        fun connect(context: Context, server: VpnServer) {
            val intent = Intent(context, ZenVpnService::class.java).apply {
                action = ACTION_CONNECT
                putExtra(EXTRA_CONFIG, server.config)
                putExtra(EXTRA_LABEL, server.displayName())
            }
            ContextCompat.startForegroundService(context, intent)
        }

        fun disconnect(context: Context) {
            val intent = Intent(context, ZenVpnService::class.java).apply {
                action = ACTION_DISCONNECT
            }
            context.startService(intent)
        }
    }
}

package com.zenpanel.app

import android.Manifest
import android.content.Intent
import android.content.pm.PackageManager
import android.net.ConnectivityManager
import android.net.Network
import android.net.NetworkCapabilities
import android.net.Uri
import android.net.VpnService
import android.os.Build
import android.os.Bundle
import android.os.Handler
import android.os.Looper
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.appcompat.app.AppCompatActivity
import androidx.core.content.ContextCompat
import com.zenpanel.app.databinding.ActivityMainBinding
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale

class MainActivity : AppCompatActivity() {

    private lateinit var binding: ActivityMainBinding
    private lateinit var store: PanelStore
    private lateinit var app: App

    private val timeFormat = SimpleDateFormat("HH:mm:ss", Locale.US)
    private val handler = Handler(Looper.getMainLooper())
    private var lastRx = 0L
    private var lastTx = 0L
    private var lastTs = 0L

    private val vpnPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->
            if (result.resultCode == RESULT_OK) startVpn() else toast(getString(R.string.vpn_permission_denied))
        }

    private val notificationPermissionLauncher =
        registerForActivityResult(ActivityResultContracts.RequestPermission()) { }

    private val connectivityManager by lazy { getSystemService(ConnectivityManager::class.java) }

    private val networkCallback = object : ConnectivityManager.NetworkCallback() {
        override fun onAvailable(network: Network) = runOnUiThread { updateStatus(true) }
        override fun onLost(network: Network) = runOnUiThread { updateStatus(isOnline()) }
        override fun onCapabilitiesChanged(network: Network, caps: NetworkCapabilities) =
            runOnUiThread { updateStatus(caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)) }
    }

    private val statsTicker = object : Runnable {
        override fun run() {
            renderVpn()
            handler.postDelayed(this, 1000)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        binding = ActivityMainBinding.inflate(layoutInflater)
        setContentView(binding.root)

        app = application as App
        store = PanelStore(this)

        binding.buttonVpnToggle.setOnClickListener { toggleVpn() }
        binding.buttonSelectServer.setOnClickListener {
            startActivity(Intent(this, ServerListActivity::class.java))
        }
        binding.buttonSearch.setOnClickListener { runSearch() }
        binding.buttonTestNotification.setOnClickListener { requestNotification() }
        binding.buttonLaunchExtension.setOnClickListener {
            startActivity(Intent(this, ExtensionActivity::class.java))
        }
        binding.buttonClearLog.setOnClickListener {
            store.clearTraffic()
            renderTraffic()
        }

        updateStatus(isOnline())
        renderTraffic()
    }

    override fun onResume() {
        super.onResume()
        handler.post(statsTicker)
    }

    override fun onPause() {
        super.onPause()
        handler.removeCallbacks(statsTicker)
    }

    override fun onStart() {
        super.onStart()
        connectivityManager?.registerDefaultNetworkCallback(networkCallback)
    }

    override fun onStop() {
        super.onStop()
        try {
            connectivityManager?.unregisterNetworkCallback(networkCallback)
        } catch (_: IllegalArgumentException) {
        }
    }

    private fun toggleVpn() {
        if (app.vpnManager.isUp) {
            ZenVpnService.disconnect(this)
            toast(getString(R.string.vpn_disconnecting))
        } else {
            requestVpn()
        }
    }

    private fun requestVpn() {
        val prepare = VpnService.prepare(this)
        if (prepare != null) {
            vpnPermissionLauncher.launch(prepare)
        } else {
            startVpn()
        }
    }

    private fun startVpn() {
        val server = app.servers.selected()
        if (server == null) {
            toast(getString(R.string.vpn_no_server))
            startActivity(Intent(this, ServerListActivity::class.java))
            return
        }
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        }
        ZenVpnService.connect(this, server)
        toast(getString(R.string.vpn_connecting))
    }

    private fun renderVpn() {
        val up = app.vpnManager.isUp
        val server = app.servers.selected()

        binding.textVpnServer.text = server?.displayName() ?: getString(R.string.vpn_no_server)
        binding.buttonVpnToggle.text =
            getString(if (up) R.string.disconnect else R.string.connect)
        binding.buttonVpnToggle.setBackgroundColor(
            ContextCompat.getColor(this, if (up) R.color.status_offline else R.color.primary)
        )
        binding.textVpnStatus.text =
            getString(if (up) R.string.vpn_connected else R.string.vpn_disconnected)
        binding.textVpnStatus.setTextColor(
            ContextCompat.getColor(this, if (up) R.color.status_online else R.color.text_muted)
        )

        val stats = app.vpnManager.statistics()
        val rx = stats?.totalRx() ?: 0L
        val tx = stats?.totalTx() ?: 0L
        val now = System.currentTimeMillis()
        var downSpeed = 0.0
        var upSpeed = 0.0
        if (lastTs != 0L && up) {
            val dt = (now - lastTs) / 1000.0
            if (dt > 0) {
                downSpeed = ((rx - lastRx) / dt).coerceAtLeast(0.0)
                upSpeed = ((tx - lastTx) / dt).coerceAtLeast(0.0)
            }
        }
        lastRx = rx
        lastTx = tx
        lastTs = now

        binding.textVpnStats.text = getString(
            R.string.vpn_stats,
            formatSpeed(downSpeed),
            formatSpeed(upSpeed),
            formatBytes(rx),
            formatBytes(tx)
        )
    }

    private fun isOnline(): Boolean {
        val cm = connectivityManager ?: return false
        val network = cm.activeNetwork ?: return false
        val caps = cm.getNetworkCapabilities(network) ?: return false
        return caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
    }

    private fun updateStatus(online: Boolean) {
        binding.textStatus.text = getString(if (online) R.string.status_online else R.string.status_offline)
        binding.textStatus.setTextColor(
            ContextCompat.getColor(this, if (online) R.color.status_online else R.color.status_offline)
        )
    }

    private fun runSearch() {
        val query = binding.inputSearch.text?.toString()?.trim().orEmpty()
        if (query.isEmpty()) return
        val url = "https://www.google.com/search?q=" + Uri.encode(query)
        store.logTraffic("${timeFormat.format(Date())}  ←  $query")
        renderTraffic()
        startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(url)))
        binding.inputSearch.setText("")
    }

    private fun requestNotification() {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU &&
            ContextCompat.checkSelfPermission(this, Manifest.permission.POST_NOTIFICATIONS) !=
            PackageManager.PERMISSION_GRANTED
        ) {
            notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
        } else {
            Notifications.show(this, getString(R.string.app_name), getString(R.string.notify_enabled_body))
        }
    }

    private fun renderTraffic() {
        val log = store.trafficLog
        binding.textTraffic.text =
            if (log.isEmpty()) getString(R.string.traffic_empty) else log.joinToString("\n")
    }

    private fun formatSpeed(bytesPerSecond: Double): String {
        val units = arrayOf("B/s", "KB/s", "MB/s", "GB/s")
        var value = bytesPerSecond
        var unit = 0
        while (value >= 1024 && unit < units.size - 1) {
            value /= 1024
            unit++
        }
        return String.format(Locale.US, "%.1f %s", value, units[unit])
    }

    private fun formatBytes(bytes: Long): String {
        val units = arrayOf("B", "KB", "MB", "GB", "TB")
        var value = bytes.toDouble()
        var unit = 0
        while (value >= 1024 && unit < units.size - 1) {
            value /= 1024
            unit++
        }
        return String.format(Locale.US, "%.1f %s", value, units[unit])
    }

    private fun toast(message: String) {
        Toast.makeText(this, message, Toast.LENGTH_SHORT).show()
    }
}

package com.zenpanel.app

import android.view.LayoutInflater
import android.view.ViewGroup
import androidx.core.content.ContextCompat
import androidx.recyclerview.widget.RecyclerView
import com.zenpanel.app.databinding.ItemServerBinding

class ServerAdapter(
    private var servers: List<VpnServer>,
    private var selectedId: String?,
    private val onSelect: (VpnServer) -> Unit,
    private val onDelete: (VpnServer) -> Unit
) : RecyclerView.Adapter<ServerAdapter.Holder>() {

    class Holder(val binding: ItemServerBinding) : RecyclerView.ViewHolder(binding.root)

    override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): Holder {
        val binding = ItemServerBinding.inflate(LayoutInflater.from(parent.context), parent, false)
        return Holder(binding)
    }

    override fun getItemCount(): Int = servers.size

    override fun onBindViewHolder(holder: Holder, position: Int) {
        val server = servers[position]
        val ctx = holder.itemView.context
        holder.binding.textTitle.text = server.displayName()
        holder.binding.textSubtitle.text = server.name
        val isSelected = server.id == selectedId
        holder.binding.root.strokeColor = ContextCompat.getColor(
            ctx,
            if (isSelected) R.color.primary else R.color.border
        )
        holder.binding.root.strokeWidth = if (isSelected) 3 else 1
        holder.binding.root.setOnClickListener { onSelect(server) }
        holder.binding.buttonDelete.setOnClickListener { onDelete(server) }
    }
}

